            while (end != -1 && end + fieldSep.length() < content.length() && content.charAt(end + fieldSep.length()) == ' ') {
                end = content.indexOf(fieldSep, end + 1);
            }
            if (end == -1) {
                actualFields.add(content.substring(start));
                break;
            } else {
                actualFields.add(content.substring(start, end));
                start = end + fieldSep.length();
            }
        }

