@Test
  public void testAssembleLongPollRefreshUrl() throws Exception {
    String someUri = someServerUrl;
    String someAppId = "someAppId";
    String someCluster = "someCluster+ &.-_someSign";
    String someNamespace = "someName";
    long someNotificationId = 1;
    Map<String, Long> notificationsMap = ImmutableMap.of(someNamespace, someNotificationId);

    String longPollRefreshUrl =
        remoteConfigLongPollService
            .assembleLongPollRefreshUrl(someUri, someAppId, someCluster, null, notificationsMap);

    assertTrue(longPollRefreshUrl.contains(someServerUrl + "/notifications/v2?"));
    assertTrue(longPollRefreshUrl.contains("appId=" + someAppId));
    assertTrue(longPollRefreshUrl.contains("cluster=someCluster%2B+%26.-_someSign"));

    int questionMarkIndex = longPollRefreshUrl.indexOf('?');
    assertTrue(questionMarkIndex > 0);
    String queryString = longPollRefreshUrl.substring(questionMarkIndex + 1);
    String[] params = queryString.split("&");
    String notificationsParam = null;
    for (String param : params) {
      if (param.startsWith("notifications=")) {
        notificationsParam = param.substring("notifications=".length());
        break;
      }
    }
    assertNotNull(notificationsParam);
    String decodedNotifications = java.net.URLDecoder.decode(notificationsParam, "UTF-8");
    com.google.gson.JsonArray jsonArray = new com.google.gson.Gson().fromJson(decodedNotifications, com.google.gson.JsonArray.class);
    assertEquals(1, jsonArray.size());
    com.google.gson.JsonObject obj = jsonArray.get(0).getAsJsonObject();
    assertEquals(someNamespace, obj.get("namespaceName").getAsString());
    assertEquals(someNotificationId, obj.get("notificationId").getAsLong());
  }

