    List<String> expectedParts = new ArrayList<>();
    for (String part : expectedXml.split("<")) {
      if (!part.trim().isEmpty()) {
        expectedParts.add("<" + part.trim());
      }
    }
    Collections.sort(expectedParts);

    assertEquals(expectedParts, actualParts);
  }

