        List<Integer> actualActive = new ArrayList<>();
        if (!inner.trim().isEmpty()) {
            for (String s : inner.split(",")) {
                actualActive.add(Integer.parseInt(s.trim()));
            }
        }
        Collections.sort(actualActive);
        assertEquals(Arrays.asList(2, 5, 6), actualActive);

        assertEquals(asJsonArray(), props.get("deactivating"));
        assertEquals(asJsonArray(3), props.get("inactive"));
    }

