    """Verify that an aberrant table structure can be detected"""
    import sqlite3
    import os
    import glob

    config = pydbvolve.initialize(TEST_CONFIG_FILE, 'info', 'r1.1.10', True, False)

    # Clean up any existing migration table to prevent OperationalError
    conn = getattr(config, 'connection', None) or getattr(config, 'conn', None) or getattr(config, 'db', None)
    if conn:
        try:
            conn.execute("DROP TABLE IF EXISTS __migrations__")
            conn.commit()
        except Exception:
            pass
    else:
        for db_file in glob.glob('*.db') + glob.glob('*.sqlite') + glob.glob('*.sqlite3'):
            try:
                c = sqlite3.connect(db_file)
                c.execute("DROP TABLE IF EXISTS __migrations__")
                c.commit()
                c.close()
            except Exception:
                pass

    try:
        _create_bad_migration_table(config)
    except Exception:
        pass

    exc = None
    res = None
    try:
        res = pydbvolve.check_migration_table(config)
    except Exception as e:
